#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Shared DDS / client helpers for trained traj highlight tests."""

from __future__ import annotations

import os
import sys
from typing import Optional

import booster_robotics_sdk_python as br


def require_highlight_sdk() -> None:
    """Fail fast when running against an SDK build without highlight APIs."""
    missing = []
    for name in (
        "TrainedTrajStatus",
        "GetTrainedTrajStatusResponse",
        "B1TrainedTrajStatusSubscriber",
        "kTopicTrainedTrajStatus",
        "LocoApiId",
    ):
        if not hasattr(br, name):
            missing.append(name)
    if missing:
        raise RuntimeError(
            "Installed booster_robotics_sdk_python is missing highlight APIs: "
            + ", ".join(missing)
            + ". Use branch ci-source-lxf-highlight-2026-07-14.qF3 (or newer)."
        )
    if not hasattr(br.LocoApiId, "kGetTrainedTrajStatus"):
        raise RuntimeError(
            "LocoApiId.kGetTrainedTrajStatus not found; "
            "please upgrade SDK to the highlight build."
        )


def default_dds_profile_path() -> Optional[str]:
    return os.environ.get("FASTRTPS_DEFAULT_PROFILES_FILE") or (
        "/opt/booster/config/dds_configs/single-board_configs/fastdds_profile_udp_only.xml"
        if os.path.isfile(
            "/opt/booster/config/dds_configs/single-board_configs/fastdds_profile_udp_only.xml"
        )
        else None
    )


def default_network_interface() -> str:
    # On robot: usb_eth0 is common; override via BOOSTER_NET_IF / argv.
    return os.environ.get("BOOSTER_NET_IF", "usb_eth0")


def parse_network_interface(argv: list[str]) -> str:
    if len(argv) >= 2 and argv[1] and not argv[1].startswith("-"):
        return argv[1]
    return default_network_interface()


def parse_robot_name(argv: list[str]) -> Optional[str]:
    if len(argv) >= 3 and argv[2] and not argv[2].startswith("-"):
        return argv[2]
    return os.environ.get("BOOSTER_ROBOT_NAME") or None


def init_channel_factory(net_if: str, domain_id: int = 0) -> None:
    profile = default_dds_profile_path()
    if profile and not os.environ.get("FASTRTPS_DEFAULT_PROFILES_FILE"):
        os.environ["FASTRTPS_DEFAULT_PROFILES_FILE"] = profile
        print(f"FASTRTPS_DEFAULT_PROFILES_FILE={profile}")
    print(f"ChannelFactory.Init(domain_id={domain_id}, iface={net_if!r})")
    br.ChannelFactory.Instance().Init(domain_id, net_if)


def create_loco_client(robot_name: Optional[str] = None) -> br.B1LocoClient:
    client = br.B1LocoClient()
    if robot_name:
        print(f"B1LocoClient.Init(robot_name={robot_name!r})")
        client.Init(robot_name)
    else:
        print("B1LocoClient.Init()")
        client.Init()
    return client


def status_to_int(status) -> int:
    if isinstance(status, int):
        return status
    return int(status)


def status_name(status) -> str:
    value = status_to_int(status)
    if value == int(br.TrainedTrajStatus.kIdle):
        return "kIdle"
    if value == int(br.TrainedTrajStatus.kRunning):
        return "kRunning"
    return f"unknown({value})"


def format_status_snapshot(status, traj_id: str) -> str:
    return (
        f"status={status_name(status)}({status_to_int(status)}), "
        f"traj_id={traj_id!r}"
    )


def usage(script: str) -> None:
    print(
        f"Usage: {script} <networkInterface> [robotName] [unittest options]\n"
        f"  networkInterface  DDS NIC, e.g. usb_eth0 on robot, eth0 from PC\n"
        f"  robotName         optional; or set BOOSTER_ROBOT_NAME\n"
        f"\nEnvironment:\n"
        f"  BOOSTER_NET_IF, BOOSTER_ROBOT_NAME, FASTRTPS_DEFAULT_PROFILES_FILE\n"
        f"\nExample:\n"
        f"  {script} usb_eth0\n"
        f"  {script} eth0 my_robot -v"
    )
